-- Demo seed: «NTNU - Matematikk 2C - Diskret matematikk (demo)»
-- Generated 2026-08-11 from the team's Monday export (course structure, columns,
-- labels and cell values). Run ONCE in the Supabase SQL editor, AFTER the
-- 20260811190000_label_progress migration. Not a migration on purpose: demo
-- data, safe to delete by deleting the board.
--
-- «Fullført arbeid» is intentionally not seeded — the app computes it (FR2),
-- and the co
mputed values should reproduce the exported Monday numbers exactly.
-- «Ansvarlig» is only set where the person maps to an existing profile (the
-- site admin); other team members have no profile until they first sign in.

do $$
declare
  v_ws    uuid;
  v_admin uuid;
  v_board uuid := '5247f639-a978-45d0-9f9f-034a9bf7abaa';
begin
  select id into v_ws from public.workspaces where name = 'Enkeleksamen';
  if v_ws is null then
    raise exception 'Fant ikke workspacen «Enkeleksamen» — kjør steg 0-SQL-en først.';
  end if;
  select id into v_admin from public.profiles where is_site_admin order by created_at limit 1;
  if v_admin is null then
    raise exception 'Fant ingen site-admin-profil — kjør steg 0-SQL-en først.';
  end if;
  if exists (select 1 from public.boards where name = 'NTNU - Matematikk 2C - Diskret matematikk (demo)') then
    raise exception 'Demo-kurset finnes allerede. Slett boardet om du vil seede på nytt.';
  end if;

  -- The on_board_created trigger makes v_admin board-admin via created_by.
  values (v_board, v_ws, 'NTNU - Matematikk 2C - Diskret matematikk (demo)', 'a0', v_admin);























  raise notice 'Demo-kurs opprettet: % kapitler, % grupper, % videoer, % celleverdier',
    8, 25, 116, 1529;
end;
$$;
